 metin: "~Ada'daki Rum çetelerinin (ENOSİS hedefli EOKA) Türk halkına yönelik baskı ve katliamları üzerine, Türkiye Garanti Antlaşması'ndan doğan yetkisini kullanarak 20 Temmuz 1974'te Kıbrıs Barış Harekâtı'nı düzenlemiştir. ~Harekât Bülent Ecevit başbakanlığındaki hükümet döneminde gerçekleştirilmiştir.",
 ipucu: "Türkiye'nin Kıbrıs'a müdahalesi 1974 yılında Garanti Antlaşması'ndaki garantörlük hakkına dayanılarak yapılmıştır.",
