 metin: "~Lozan Antlaşması'na göre İstanbul'daki Rumlar ile Batı Trakya'daki Türkler dışında, Türkiye ve Yunanistan'daki azınlıkların yer değiştirmesi kararlaştırılmıştır. ~Yunanistan'ın etablı (yerleşik) olma kuralını suistimal etmesi iki ülke arasında uzun süreli bir bunalıma yol açmıştır.",
 ipucu: "Nüfus mübadelesi sorunu, Yunanistan'ın İstanbul'da daha fazla Rum bırakmak istemesi (etaplı sorunu) nedeniyle çıkmıştır.",
