 baslik: "Montrö Boğazlar Sözleşmesi (1936)",
 metin: "~Lozan'da kurulan uluslararası Boğazlar Komisyonu'nun yetkileri kaldırılmış, Boğazların yönetimi ve savunması tamamen Türkiye'ye verilmiştir. ~Böylece Lozan'ın eksik kalan yönlerinden biri lehimize çözülmüştür.",
 ipucu: "Montrö Sözleşmesi ile Boğazlar Komisyonu kaldırılmış ve Boğazlar üzerindeki tam egemenlik hakkı Türkiye'ye geçmiştir.",
