 baslik: "Ankara'nın Başkent Olması (13 Ekim 1923)",
 metin: "~Milli mücadelenin merkezi olan Ankara, stratejik ve güvenli konumundan dolayı 13 Ekim 1923 tarihinde kanunla Türkiye devletinin başkenti ilan edilmiştir.",
 ipucu: "Ankara'nın başkent olması cumhuriyetin ilanından kısa bir süre önce, 13 Ekim 1923'te gerçekleşmiştir.",
