 baslik: "Kadınlara Siyasi Hakların Verilmesi (1930 - 1934)",
 metin: "~Türk kadınlarına sırasıyla 1930'da belediye seçimlerine, 1933'te muhtarlık seçimlerine ve 1934'te milletvekili seçme ve seçilme hakları tanınmıştır.",
 ipucu: "Kadınlara tanınan siyasi haklar sırasıyla Belediye, Muhtarlık ve Milletvekilliği (BMV) olarak ezberlenebilir.",
