 metin: "~Köylünün sırtındaki en ağır yüklerden biri olan ve ürün üzerinden alınan Aşar vergisi 1925 yılında kaldırılmıştır. ~Türkiye Merkez Bankası, Sümerbank, Etibank ve İş Bankası gibi kurumlar milli ekonomiyi desteklemek için kurulmuştur.",
 ipucu: "Aşar vergisinin kaldırılması köylünün ekonomik rahatlamasını sağlamış, tarımda ve sanayide milli bankalar faaliyete geçmiştir.",
