 metin: "~Türkiye Cumhuriyeti'nin ilk muhalefet partisi olarak Kâzım Karabekir, Rauf Orbay, Ali Fuat Cebesoy ve Refet Bele tarafından 1924'te kurulmuştur. ~Liberal ekonomi modelini savunmuş, ancak Şeyh Sait İsyanı sonrasında Takrir-i Sükun Kanunu ile kapatılmıştır.",
 ipucu: "Terakkiperver Cumhuriyet Fırkası ilk muhalefet partisidir ve kurucuları arasında kurtuluş mücadelesinin önemli komutanları yer alır.",
