 metin: "~Atatürk'ün isteğiyle Ali Fethi Okyar tarafından 1930'da kurulan ikinci muhalefet partisidir. ~Parti çevrelerindeki gerici yapılanmalar ve Menemen Olayı (Kubilay'ın şehit edilmesi) üzerine Ali Fethi Okyar partiyi kendi feshetmiştir, çok partili hayata geçiş ertelenmiştir.",
 ipucu: "Serbest Cumhuriyet Fırkası 1930'da kurulmuş, Menemen olayı sonrasında kendisini feshetmiştir.",
