    etiketler: ["1. Ünite 1. Altkonu: Trablusgarp Savaşı (1911 - 1912) - Savaşın Sona Ermesi"],
    metni: "~Derne ve Tobruk’ta Mustafa Kemal, Bingazi’de Enver Bey İtalyanların ilerleyişini durdurmuştur. ~İtalya Osmanlı Devleti’ni barışa zorlamak için Balkan Savaşları’nın da çıkmasını fırsat bilerek On İki Ada ve Rodos’u işgal etmiş, Çanakkale Boğazı’nı kuşatmış Akabe ve Beyrut’u bombalamıştır. ~Bu gelişmeler üzerine Osmanlı barış istemek zorunda kalmış ve iki devlet arasında Uşi Antlaşması imzalanmıştır.",
    tuzaklar: {
        aciklama: "Mustafa Kemal’in Derne ve Tobruk’ta, Enver Bey’in ise Bingazi’de mücadele ettiği bilgisi soru çözerken karıştırılmamalıdır. İtalya'nın baskıyı artırmak için Akabe ve Beyrut'u bombaladığı, On İki Ada ve Rodos'u işgal ettiği unutulmamalıdır.",
        hap: [
            "Balkan Savaşları'nın çıkması, Osmanlı Devleti'ni Trablusgarp'ta barış imzalamaya mecbur bırakan en kritik gelişmedir."
        ]
    },
    favoriMi: false,
