    metni: "~Osmanlı Devleti Kuzey Afrika’daki son toprak parçasını kaybetti (Trablusgarp). ~Mustafa Kemal Kolağası (Yüzbaşı) rütbesinden, Binbaşılığa yükseldi. ~Mustafa Kemal’in ilk askeri başarısıdır. ~Bu savaş Mustafa Kemal’in sömürgeciliğe karşı ilk savaşıdır. ~Osmanlı Devleti’nin zayıflığı anlaşıldı. ~Dünya tarihinde uçak ilk kez bu savaşta kullanılmıştır.",
