        hap: [
            "Balkan Savaşları sonucunda Osmanlıcılık fikri önemini yitirmiş, yerine **Türkçülük** akımı kazanmıştır.",
            "Ordunun modernize edilmesi için Alman subayların getirilmesi Osmanlı-Almanya yakınlaşmasının ilk büyük adımıdır."
        ]
