    etiketler: ["1. Ünite / I. Dünya Savaşı (1914 - 1918) - Savaşın Nedenleri (Genel ve Özel Nedenler)"],
    metni: "Savaşın Genel Nedenleri ~Fransız İhtilali ile birlikte yayılan milliyetçilik akımı, ~Sanayi İnkılabı ile başlayan sömürgecilik yarışı, ham madde ve pazar arayışı, ~Devletler arasında görülen bloklaşmalar ve silahlanma yarışıdır. Savaşın Özel Nedenleri ~Fransa’nın Almanya’ya kaptırdığı Alsas - Loren bölgesini geri almak istemesi, ~Rusya’nın Balkan politikası (Panslavizm), ~Japonya’nın Almanya’nın sömürgelerini elde etmek istemesi, ~İtalya’nın Akdeniz’de sömürge elde etmek istemesi, ~İngiltere ve Almanya arasındaki ekonomik mücadele, ~Bulgaristan’ın Ege Denizi’ne sahip olmak istemesi, ~Avusturya - Macaristan ile Sırbistan arasındaki Bosna - Hersek sorunu, ~Osmanlı Devleti’nin kaybettiği toprakları geri almak istemesi",
