    metni: "~Tarafsızlığını ilan etmiştir. ~Boğazları yabancı gemilere kapatmıştır. ~Seferberlik ilan etmiştir (Her an savaşa girme ihtimaline karşı). ~Kapitülasyonları tek taraflı olarak kaldırmıştır.",
