    maddeNo: 20101,
    baslik: "2. Ünite / Kurtuluş Savaşı (Hazırlık Dönemi) - Mustafa Kemal'in İstanbul'a Gelişi (1918)",
    etiketler: ["2. Ünite / Kurtuluş Savaşı (Hazırlık Dönemi) - Mustafa Kemal'in İstanbul'a Gelişi (1918)"],
    metni: "MUSTAFA KEMAL’İN İSTANBUL’A GELİŞİ (1918) ~Yıldırım Orduları Grup Komutanlığı’nın kaldırılması ve Mondros’un maddelerine karşı çıkması sonucu Suriye - Filistin Cephesi’ndeki Mustafa Kemal İstanbul’a çağrılmıştır. ~13 Kasım 1918’de Mustafa Kemal İstanbul’a gelmiştir. Aynı gün İtilaf Devletleri İstanbul önlerinde gemilerini demirlemişlerdir. Bu tarih İstanbul’un fiilen işgal tarihidir. M. Kemal bu durumu görünce “Geldikleri gibi giderler” demiştir. ~Mustafa Kemal İstanbul’a geldikten sonra İstanbul’da bir dizi çalışmalarda bulunmuştur. Bunlar: • Fethi Bey ile birlikte Minber gazetesini çıkarmıştır. • Tevfik Paşa Hükümetine karşı tavır almıştır. • İzzet Paşa Hükümetinde Harbiye Nazırı olmak istemiştir. • Padişah Vahdettin ile görüşmelerde bulunmuştur. ~İstanbul’da yapabileceği bir şey olmadığını görünce Anadolu’ya geçme yollarını aramıştır",
    tuzaklar: {
        aciklama: "Mustafa Kemal'in İstanbul'a geldiği 13 Kasım 1918 tarihinin hukuki işgal tarihi olduğu ya da İtilaf gemilerinin Mondros Antlaşması'nın imzalandığı gün limana demirlediği şeklindeki ifadeler sınav sorularında sıkça çeldirici olarak kullanılır; bu tarih İstanbul'un **fiilen işgal** tarihidir. Ayrıca Minber gazetesinin Fethi Bey ile birlikte çıkarıldığı bilgisi sıkça sorgulanır.",
        hap: [
            "Mustafa Kemal, Yıldırım Orduları Grup Komutanlığı'nın kaldırılmasıyla 13 Kasım 1918'de İstanbul'a gelmiş, \"Geldikleri gibi giderler\" sözünü söylemiş, Fethi Bey ile Minber gazetesini çıkarmış ve İstanbul'da kalıcı bir çözüm olamayacağını görerek Anadolu'ya geçiş yollarını aramıştır."
        ]
    },
