    etiketler: ["2. Ünite / Kurtuluş Savaşı (Hazırlık Dönemi) - Erzurum Kongresi (23 Temmuz - 7 Ağustos 1919) - Kararları"],
    metni: "Erzurum Kongresi (23 Temmuz - 7 Ağustos 1919) Kararları ~Millî sınırlar içinde vatan bir bütündür, parçalanamaz. Her türlü işgale karşı bir bütün olarak mücadele edilecektir. ~İstanbul Hükümeti üstüne düşen görevi yerine getirmezse geçici bir hükümet kurulacaktır. Hükümeti Millî Kongre seçecek, kongre toplanmazsa Temsil Heyeti bu görevi yerine getirecektir. Hristiyan halka siyasi hâkimiyetimizi ve sosyal dengemizi bozacak ayrıcalıklar tanınamaz. ~Manda ve himaye kabul edilemez. Kuva-yı Millîye’yi etkin ulusal iradeyi hakim kılmak esastır. Mebusan Meclisi toplanmalıdır. ~Ulusal irade ve ulusal güçler saltanat ve halife makamını kurtaracaktır. Siyasi, ekonomik ve sosyal dengemiz korunmak şartıyla yabancı ülkelerden yardım alınabilir.",
    tuzaklar: {
        aciklama: "Erzurum Kongresi kararlarında millî sınırların ilk kez Amasya Genelgesi'nde çizildiği, manda ve himaye fikrinin ilk kez Sivas Kongresi'nde reddedildiği ya da Hristiyan azınlıklara siyasi hakimiyeti bozacak ayrıcalıklar tanınmasının desteklendiği şeklindeki ifadeler sınav sorularında çeldirici olarak kullanılır; millî sınırlardan ilk kez Erzurum Kongresi'nde bahsedilmiş, manda ve himaye kesin olarak burada reddedilmiş ve azınlıklara siyasi hakimiyetimizi bozacak ayrıcalıklar tanınamayacağı vurgulanmıştır. Ayrıca geçici hükümet kurma fikri ve Mebusan Meclisi'nin toplanması gerektiği vurgusu bu kongrede yer almıştır.",
        hap: [
            "Erzurum Kongresi kararları arasında \"Vatan bir bütündür, parçalanamaz\" ilkesiyle millî sınırlar ilk kez çizilmiş, \"Manda ve himaye kabul edilemez\" ifadesiyle sömürgeci yönetimler ilk kez reddedilmiş ve geçici hükümet kurularak İstanbul Hükümeti'ne alternatif bir yönetim fikri ilk defa gündeme getirilmiştir."
        ]
    },
    favoriMi: false,
