    metni: "Önemi ve Sonuçları ~Elazığ Valisi Ali Galip ve Ankara Valisi Muhittin Paşa kongrenin toplanmasını engellemeye çalışmıştır. ~Temsil Heyeti’nin görev alanı, üye sayısı ve yetkisi genişletilmiştir. ~Temsil Heyeti ilk defa yürütme yetkisini kullanmıştır (Batı Cephesi’ne Ali Fuat Cebesoy atandı.). ~İstanbul Hükümeti’nin engellemelerine tepki olarak İstanbul Hükümeti ile ilişkiler kesilmiş ve bunun sonucunda Damat Ferit Paşa Hükümeti istifa ederek yerine Ali Rıza Paşa Hükümeti kurulmuştur. ~Bu durum Temsil Heyeti’nin İstanbul Hükümetine karşı kazandığı ilk siyasi başarısıdır. ~Kongrede en çok tartışılan iki konu; kongre başkanlığı ile manda ve himaye konusudur. ~Manda ve himaye son ve kesin olarak reddedilmiştir. ~Kongre başkanlığına Mustafa Kemal seçilmiştir.",
    tuzaklar: {
        aciklama: "Sivas Kongresi'nin İstanbul Hükümeti tarafından engellendiği, Temsil Heyeti'nin ilk yürütme yetkisini Amasya Genelgesi'nde ya da Erzurum Kongresi'nde kullandığı, yahut Damat Ferit Paşa Hükümeti'nin Temsil Heyeti ile anlaşarak görevine devam ettiği şeklindeki ifadeler sınav sorularında çeldirici olarak kullanılır; Sivas Kongresi engellenememiş, Temsil Heyeti ilk yürütme yetkisini Sivas'ta (Ali Fuat Cebesoy'un Batı Cephesi komutanlığına atanmasıyla) kullanmış ve bu süreç Damat Ferit Paşa Hükümeti'nin istifasına yol açmıştır.",
        hap: [
            "Sivas Kongresi, İstanbul Hükümeti'nin engelleme girişimlerine rağmen gerçekleştirilmiştir. Temsil Heyeti, Batı Cephesi'ne Ali Fuat Cebesoy'u atayarak ilk kez yürütme yetkisini kullanmıştır. İstanbul Hükümeti ile tüm haberleşmenin kesilmesi sonucunda Damat Ferit Paşa istifa etmiş, yerine Ali Rıza Paşa Hükümeti gelmiş; böylece Temsil Heyeti İstanbul'a karşı ilk büyük siyasi zaferini elde etmiştir."
        ]
    },
