        aciklama: "I. TBMM'nin aldığı ilk kararın Teşkilat-ı Esasiye'yi ilan etmek olduğu, Lozan Antlaşması'nı imzaladığı ya da halifeliği kaldırdığı şeklindeki ifadeler sınav sorularında çeldirici olarak kullanılır; meclisin aldığı ilk karar Ağnam vergisinin arttırılmasıdır, Lozan'a katılmış ancak antlaşmayı II. TBMM imzalamıştır ve I. TBMM sadece saltanatı kaldırmıştır (halifelik II. TBMM döneminde kaldırılmıştır).",
        hap: [
            "I. TBMM; Ağnam vergisinin arttırılması kararını ilk olarak almış, Hıyanet-i Vataniye Kanunu'nu çıkararak ve İstiklal Mahkemelerini kurarak otoritesini korumaya çalışmıştır. Kurtuluş Savaşı'nı yönetmiş, Teşkilat-ı Esasiye'yi ilan etmiş ve saltanatı kaldırmıştır."
        ]
