    etiketler: ["2. Ünite / Kurtuluş Savaşı (Hazırlık Dönemi) - I. TBMM’ye Karşı Çıkan Ayaklanmalar - Ayaklanmaların Sonuçları"],
    metni: "Ayaklanmaların Sonuçları ~Hıyanet-i Vataniye Kanunu çıkarıldı. (İlk yargılanan kişi Damat Ferit Paşa’dır.) ~Askerden kaçmaları önlemek için Firariler Kanunu çıkarıldı. ~Kuva-yı Millîye kaldırıldı. Düzenli ordunun kurulması hızlandı. İstanbul Hükümeti ile haberleşmenin kesilmesi kararı alındı. Ankara Müftüsü Rıfat Börekçi tarafından Milli Mücadele’yi destekleyen fetva yayımlandı. Vergilerin TBMM adına toplanması kararı alındı. ~Kurtuluş Savaşı’nın kazanılması uzun süre almıştır. ~İstiklal Mahkemeleri kuruldu. İstiklal Mahkemelerinin üyeleri milletvekilleriydi. Halkı bilgilendirmek amacıyla İrşad (Öğüt) Heyetleri kurulmuştur.",
    tuzaklar: {
        aciklama: "Ayaklanmaların sonuçları arasında İstiklal Mahkemeleri üyelerinin bağımsız sivil yargıçlardan seçildiği, Hıyanet-i Vataniye Kanunu'nda ilk yargılananın Mustafa Kemal olduğu ya da Kuva-yı Millîye'nin güçlenerek varlığını sürdürdüğü şeklindeki ifadeler sınav sorularında çeldirici olarak kullanılır; İstiklal Mahkemesi üyeleri milletvekillerinden oluşmuştur, Hıyanet-i Vataniye'de ilk yargılanan kişi Damat Ferit Paşa'dır ve Kuva-yı Millîye bu süreçte kaldırılmıştır.",
        hap: [
            "Ayaklanmalar sonucunda TBMM otoritesini korumak için Hıyanet-i Vataniye ve Firariler kanunlarını çıkarmış, milletvekillerinden oluşan İstiklal Mahkemelerini kurmuş, düzenli orduya geçiş hızlanmış, Rıfat Börekçi fetva yayımlamış ve halkı aydınlatmak için İrşad Heyetleri görevlendirmiştir; ancak bu isyanlar Kurtuluş Savaşı'nın kazanılmasını geciktirmiştir."
        ]
    },
    favoriMi: false,
    cipMi: false
