    metni: "Bilecik Görüşmeleri (5 Aralık 1920) ~TBMM Başkanı Mustafa Kemal ile İstanbul Hükümeti adına içişleri Bakanı Ahmet İzzet Paşa ile Bahriye Nazırı Salih Paşa arasında yapılmıştır. ~Görüşmeler sonrasında İstanbul heyetinin İstanbul’a dönmesine izin verilmemiştir. Heyet bir süre Ankara’da alıkonulmuştur. ~Bilecik görüşmeleriyle İstanbul Hükümeti, TBMM’yi resmen tanımıştır.",
