    baslik: "2. Ünite / Kurtuluş Savaşı (Hazırlık Dönemi) - Sevr Barış Antlaşması (10 Ağustos 1920) - Kararları",
    etiketler: ["2. Ünite / Kurtuluş Savaşı (Hazırlık Dönemi) - Sevr Barış Antlaşması (10 Ağustos 1920) - Kararları"],
    metni: "SEVR BARIŞ ANTLAŞMASI (10 AĞUSTOS 1920) Sevr Barış Antlaşması, Damat Ferit Paşa’nın eski komutan ve nazırlardan oluşturduğu Saltanat Şurası (Hadi Paşa, Rıza Tevfik Bey, Reşat Halis Bey) tarafından imzalanmıştır. Kararları ~İstanbul, Osmanlı’nın başkenti olarak kalacak, azınlık hakları korunmazsa burası da alınacaktır. ~Boğazlar uluslararası bir komisyon tarafından yönetilecektir. ~Zorunlu askerlik kaldırılacaktır. ~Kara ordusu ve deniz ordusu sınırlandırılacaktır. ~Osmanlı maliyesi İtilaf Devletleri’nin kontrolünde olacaktır. ~Kapitülasyonlar bütün devletlere verilecektir. ~Osmanlı, savaş tazminatı ödeyecektir. ~Doğu Trakya ve Batı Anadolu Yunanlılara verilecektir. ~Adana, Urfa, Antep, Suriye Fransa’ya verilecektir. ~Batı Anadolu’nun bir bölümü ve Konya İtalya’ya verilecektir. ~Doğuda Ermeni ve Kürt devletleri kurulacaktır. ~Rodos ve On iki Ada İtalya’ya; Ege Adaları Yunanistan’a verilecektir.",
    tuzaklar: {
        aciklama: "Sevr Barış Antlaşması kararlarında zorunlu askerliğin korunduğu, maliyenin Osmanlı kontrolünde kaldığı ya da kapitülasyonların kaldırıldığı şeklindeki ifadeler sınav sorularında çeldirici olarak kullanılır; antlaşmada zorunlu askerlik kaldırılmış, maliye İtilaf Devletleri kontrolüne verilmiş ve kapitülasyonlar tüm devletlere yaygınlaştırılmıştır.",
        hap: [
            "Damat Ferit Paşa'nın oluşturduğu Saltanat Şurası tarafından imzalanan Sevr Barış Antlaşması; Osmanlı'nın maliyesini, ordusunu ve topraklarını İtilaf Devletleri'nin kontrolüne bırakarak devleti savunmasız ve bağımsızsız bırakmayı amaçlayan ağır hükümler içermiştir."
        ]
    },
