    etiketler: ["2. Ünite / Kurtuluş Savaşı (Hazırlık Dönemi) - Millî Mücadele Dönemi’nde Basın (Milli Mücadele’yi Destekleyen Basın - Bölüm 2)"],
    metni: "Babalık: Konya’da çıkarılmıştır. Tanin: Hüseyin Cahit tarafından İstanbul’da yayımlanmıştır. Halifeliğin kaldırılması için gönderilen Agoltan ve Emir Ali’nin mektuplarını yayımladı. Dergâh: Birçok ünlü yazarın bir araya gelmesiyle çıkarılan dergidir. Le Pays (Vatan): Doğu illerinin Türk yurdu olduğunu belirten ve Fransızca yayın yapan gazetedir. Doğu Anadolu Müdafaa-i Hukuk Cemiyeti’nin yayın organıdır. Hadisat: Doğu illerinin Türk yurdu olduğunu belirten gazetedir. Doğu Anadolu Müdafaa-i Hukuk Cemiyeti’nin yayın organıdır. Mardin Gazetesi: Yeni Türk harfleri ile basılan ilk gazetedir. İzmir’e Doğru: Vasıf Çınar tarafından İzmir’de çıkarılmıştır. Vakit: Türkiye’de çok renkli yayın yapan ilk gazetedir. Öğüt: Sırasıyla Afyon, Konya ve Ankara’da basıldı. İstikbal: Trabzon’da yayın hayatına başlamıştır. Tasvir-i Efkâr: 1862’de yayın hayatına başlamıştır. Küçük Mecmua: Turancılık fikrini savunan gazete Ziya Gökalp tarafından Diyarbakır’da çıkarılmıştır. Tercüman: TBMM’nin cephe haberlerini aldığı gazetedir.",
