    metni: "~Ermeniler Osmanlı’ya en son isyan eden millettir. ~Rusya’nın kışkırtmaları sonucu Ermeni Sorunu doğmuştur. ~Ermeni Sorunu ilk kez 1878 Berlin Anlaşması’yla ortaya çıkmıştır. ~I. Dünya Savaşı’nda Tehcir Yasası ile Ermeniler Suriye’ye ve Lübnan’a zorunlu göç ettirilmiştir. ~Wilson İlkeleri, Mondros Ateşkes’i ve Paris Barış Konferansı’nda Ermenilerle ilgili kararlar alınmıştır. ~Kurtuluş Savaşı’nda Ermenilerin olumsuz çalışmaları üzerine Doğu Cephesi Komutanı Kazım Karabekir komutasındaki 15. Kolordu’nun Ermenilere yönelik taarruz hareketine geçmesinin ardından Ermeniler Gümrü Antlaşması’nı imzalamak zorunda kalmıştır.",
