    etiketler: ["3. Ünite / Kurtuluş Savaşı (Muhabere Dönemi) - Gümrü Antlaşması (3 Aralık 1920)"],
    metni: "GÜMRÜ ANTLAŞMASI (3 ARALIK 1920) ~Bu antlaşma Kazım Karabekir tarafından imzalanmıştır. ~Türk birliklerin başarıları Ermenileri barış istemek zorunda bırakmıştır. ~Bu antlaşmayla; Aras Nehri ve Çıldır Gölü sınır kabul edildi. Kars, Kağızman, Kulp, Sarıkamış ve Iğdır Türklere verildi. ~Ermeniler Sevr Anlaşması’ndan vazgeçti ve Misakımillî’yi kabul etti. ~Ermenistan ister ise Türk tarafı siyasi ve askeri yardımda bulunabilecektir. ~TBMM’nin ilk anlaşmasıdır. TBMM’yi ve Misakımillî’yi tanıyan ilk devlet Ermenistan’dır. ~TBMM’nin siyasi ve askeri arenada ilk başarısıdır. ~Türkiye Devleti tabirinin kullanıldığı ilk antlaşmadır.",
