    metni: "~Kütahya-Eskişehir Savaşı sonrası, Sakarya Savaşı öncesi çıkarılmıştır. ~Meclis yetkilerini üç aylığına Mustafa Kemal’e vermiştir. ~Mustafa Kemal kararları çabuk almak ve kanun çıkarmak için böyle bir yola başvurmuştur. ~Bu yetkiye dayanarak Tekalif-i Milliye Emirleri’ni çıkarmıştır. ~Bu kanun ile Mustafa Kemal, Amasya Genelgesi’nden sonra tekrar orduya dönmüştür",
