    metni: "~Mustafa Kemal çıkarmıştır. Ordunun ihtiyaçları için halktan toplanan yardımları içerir. Genel seferberlik anlamına gelir. ~Bu emirleri yerine getirmek için İstiklal Mahkemeleri (Ankara, Konya, Samsun, Yozgat ve Kastamonu’da) yeniden kurulmuştur. Her ilde Tekalif-i Millîye Komisyonu kurulmuştur",
