    metni: "~Sovyet Rusya denetimindeki Gürcistan, Azerbaycan, Ermenistan (Kafkas Cumhuriyetleri) ile TBMM arasında imzalanmıştır. Nahcivan’a özerklik verilecek, Azerbaycan’a bağlı olacak ~Moskova Antlaşması hariç daha önce yapılan anlaşmalar geçersiz sayılacak ~Üç devlet de kapitülasyonların kaldırılmasını kabul edecek ~Türkiye’nin tanımadığı bir antlaşmayı bu üç devlet de tanımayacak ~Taraflar arasında ticaret, gümrük, sağlık ve güvenlik konularında ortak tedbirler alınacak ~Doğu sınırımız kesin olarak çizilmiştir. Ardahan Türkiye’de, Batum Gürcistan’da kalmıştır",
