    metni: "~Fransa ve TBMM arasındaki savaş sona erecek ~Çukurova boşaltılacak ~Suriye sınırları içinde yer alan Caber Kalesi Türk toprağı sayılacak ~Suriye’de kalan Caber Kalesi (Süleyman Şah Türbesi) Türk toprağı sayılacak, burada Türk bayrağı dalgalanacaktı. Süleyman Şah Türbesi’nin ilk ve orijinal yeri Suriye toprağı içinde yer alan El-Assad Gölü civarıdır. Bu türbe 1973’te Suriye’deki Karakazak Köyü’ne, 2015’te ise Fırat Şah Operasyonu ile Suriye’nin Eşme Köyü’ne taşınmıştır. ~Savaş esirleri karşılıklı bırakılacak ~Hatay ve İskenderun’da özel bir yönetim kurulacak ve Fransa mandasındaki Suriye’ye bırakılacak ~Fransızlar çekilirken bazı askeri ve lojistik malzemeleri TBMM’ye bıraktı.",
