    metni: "Serbest Cumhuriyet Fırkası (12 Ağustos 1930) ~Mustafa Kemal’in isteği ile Fethi Okyar tarafından kurulmuştur. ~Limanlardaki tekelci uygulamalara son vermeyi amaçlamıştır. ~1929 Dünya Ekonomik Krizi’nin aşılmasında etkili olmuştur. ~Türk parasının değerini koruyacak tedbirlerin alınmasını savunmuştur. ~Ekonomide liberalizmi savunmuştur. ~Kadınlara siyasi hakların verilmesi savunulmuştur. ~Seçimlerin tek dereceli olması istenmiştir. ~Programında cumhuriyetçilik, milliyetçilik ve laiklik yer almıştır. ~Yabancı sermayenin ülkeye girişini savunmuştur. Partinin Kurucuları Genel başkan: Ali Fethi Okyar Genel sekreter: Mehmet Nuri Conker",
