    etiketler: ["6. Ünite / Atatürk Dönemi Türk Dış Politikası - Türk Dış Politikasının Temel İlkeleri"],
    metni: "~Atatürk, Misakımillî ile yeni Türk devleti için korunması mümkün gerçekçi bir sınır çizmiştir. ~Atatürk’ün “Yurtta barış, cihanda barış” sözü doğrultusunda geliştirilen dış politikasının ilkeleri şunlardır: • Milli sınırlarımız içinde varlığımızı korumak • Gerçekleştirilmeyecek emeller peşinde koşmamak • Diğer devletlerin iç işlerine karışmamak • Komşu ülkelerle dostluk ilişkilerini geliştirmek • Milli politikayı uygularken kamuoyunu dikkate almak • Uluslararası hukuka bağlı kalmak • Türk ulusunun uluslararası alanda saygınlığını artırmak • Bağımsızlığımıza saygı duyan devletlerle her alanda ilişkileri geliştirmek • Dünyadaki gelişmeleri yakından takip etmek",
    tuzaklar: {
        aciklama: "Sınavlarda Atatürk döneminde dış politikada yayılmacı, saldırgan veya irredentist politikaların izlendiği, başka devletlerin iç işlerine müdahale edildiği şeklinde çeldiriciler kurulur; oysa Türk dış politikası barışçıl, gerçekçi, Misakımillî sınırları saklı tutularak uluslararası hukuka saygılı bir yapıdadır.",
        hap: [
            "“Yurtta barış, cihanda barış” ilkesi Atatürk dönemi dış politikasının temel rehberidir. Akılcılık, uluslararası dengeleri gözetmek, mütekabiliyet ve millî menfaatleri korumak esas alınmıştır."
        ]
    },
    favoriMi: false,
    cipMi: false
