    metni: "~Lozan’da bu sorun çözülememiştir. ~Yunanistan, Türkiye’de daha çok Rum halkını bırakmak isteyince ilişkiler gerginleşti. ~1928 yılında bu sorunlar Milletler Cemiyeti’nde görüşüldüğü halde çözülemedi. ~1930 Haziran ayındaki anlaşmayla sorun çözümlendi. Bu antlaşma ile İstanbul Rumları ile Batı Trakya Türklerinin hepsi yerleşik sayıldı (Ahali Mübadelesi). ~Bu sorunun çözülmesi Türkiye’nin Milletler Cemiyetine üye olmasında ve Balkan Antantı’nın imzalanmasında etkili olmuştur. ~Venizelos, Atatürk’ü 1934 yılında Nobel Barış Ödülü’ne aday göstermiştir.",
